const fs = require('fs');

// Fix Invoices.jsx - add watermark and fix encoding
let c = fs.readFileSync('src/pages/Invoices.jsx', 'utf8');

// Fix encoding
c = c.replace(/â‚¦/g, '₦');
c = c.replace(/â€"/g, '—');

// Update buildInvoiceHTML to accept isPaid parameter
c = c.replace(
  'const buildInvoiceHTML = (invoice, businessName = \'My Business\') => {',
  'const buildInvoiceHTML = (invoice, businessName = \'My Business\', isPaid = false) => {'
);

// Add watermark before closing body tag
c = c.replace(
  '<p style="font-size:11px;color:#CBD5E1;">Generated by Flowora &middot; Thank you for your business</p>',
  `<p style="font-size:11px;color:#CBD5E1;">Generated by FloworaX &middot; Thank you for your business</p>
  \${!isPaid ? \`<div style="text-align:center;margin-top:24px;padding:12px;background:#EEF4FF;border-radius:8px;border:1px solid #BFDBFE;">
    <p style="font-size:11px;color:#185FA5;font-weight:700;margin:0;">⚡ Powered by FloworaX &middot; <a href="https://floworax.com" style="color:#185FA5;">floworax.com</a> &middot; Upgrade to remove this watermark</p>
  </div>\` : ''}`
);

// Update downloadInvoicePDF call to pass isPaid
c = c.replace(
  'const downloadInvoicePDF = (invoice, biz) => {',
  'const downloadInvoicePDF = (invoice, biz, isPaid = false) => {'
);
c = c.replace(
  'const html = buildInvoiceHTML(invoice, biz);',
  'const html = buildInvoiceHTML(invoice, biz, isPaid);'
);

// Update all calls to downloadInvoicePDF to pass user plan
c = c.replace(
  /downloadInvoicePDF\(([^,)]+),\s*([^)]+)\)/g,
  'downloadInvoicePDF($1, $2, user?.plan === \'paid\')'
);

fs.writeFileSync('src/pages/Invoices.jsx', c, 'utf8');
console.log('Fixed Invoices.jsx with watermark');
